#pragma once
#include <array>
#include <cstdint>
namespace ks {
class StatePresetSaveTask final {public:enum class Stage {PackFields,ReadCurrent,SetProgramSource,StorePage,ReadLateCurrent,SetLateProgramSource,ReadProgram,CompareBank,AdmitBank,CompareAlias,AdmitAlias,RetainProgram,SetAlias,WriteAlias,StoreAlias,RestoreProgram,WriteOriginal,SetTimerTicks,SetTimerCallback,ScheduleTimer,ReturnSave,AwaitChild,Complete};enum class Read {Current,LateCurrent,Program};enum class Write {Alias,Restore};enum class Child {Pack,Store,Alias,Timer};
 Stage stage()const{return phase_;}Stage resumeStage()const{return resume_;}bool complete()const{return phase_==Stage::Complete;}bool awaitingChild()const{return phase_==Stage::AwaitChild;}Child child()const{return child_;}bool resumeChild(){if(!awaitingChild())return false;phase_=resume_;return true;}static constexpr unsigned timerTicks(){return 250;}
 unsigned nextClocks(unsigned storeClocks=3)const{constexpr std::array<unsigned,21> costs{{20,18,9,20,18,9,6,3,3,3,3,11,3,6,20,11,12,6,9,20,17}};return unsigned(phase_)>=costs.size()?0:phase_==Stage::WriteOriginal?costs[unsigned(phase_)]-3+storeClocks:costs[unsigned(phase_)];}
 template<class Reader,class Writer>unsigned advanceBefore(unsigned available,Reader&& read,Writer&& write,unsigned storeClocks=3){unsigned used=0;while(const auto cost=nextClocks(storeClocks)){if(cost>available-used)break;switch(phase_){case Stage::PackFields:await(Child::Pack,Stage::ReadCurrent);break;case Stage::ReadCurrent:(void)read(Read::Current);next();break;case Stage::StorePage:await(Child::Store,Stage::ReadLateCurrent);break;case Stage::ReadLateCurrent:(void)read(Read::LateCurrent);next();break;case Stage::ReadProgram:program_=uint16_t(read(Read::Program));next();break;case Stage::AdmitBank:phase_=uint8_t(program_>>8)<=4?Stage::SetTimerTicks:Stage::CompareAlias;break;case Stage::AdmitAlias:phase_=uint8_t(program_)==49?Stage::SetTimerTicks:Stage::RetainProgram;break;case Stage::WriteAlias:write(Write::Alias,(program_&0xff00)|49);next();break;case Stage::StoreAlias:await(Child::Alias,Stage::RestoreProgram);break;case Stage::WriteOriginal:write(Write::Restore,uint8_t(program_));next();break;case Stage::ScheduleTimer:await(Child::Timer,Stage::ReturnSave);break;case Stage::ReturnSave:phase_=Stage::Complete;break;default:next();break;}used+=cost;}return used;}
private:void next(){phase_=Stage(unsigned(phase_)+1);}void await(Child c,Stage s){child_=c;resume_=s;phase_=Stage::AwaitChild;}Stage phase_=Stage::PackFields,resume_=Stage::Complete;Child child_=Child::Pack;uint16_t program_=0;
};}
